import{_ as p,a0 as i,w as l,s as h,I as o,x as t,a1 as e,A as s,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Thonny：在學校教授 Python 編程的理想 IDE | LCTT x X-CMD","titleTemplate":false,"description":"Thonny：在學校教授 Python 編程的理想 IDE | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Thonny：在學校教授 Python 編程的理想 IDE | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Thonny：在學校教授 Python 編程的理想 IDE | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220613 Thonny is an Ideal IDE for Teaching Python Programming in Schools","title":"Thonny：在學校教授 Python 編程的理想 IDE","tag":"202206","desc":""},"relativePath":"202206/20220613 Thonny is an Ideal IDE for Teaching Python Programming in Schools.md","filePath":"[post].md"}'),d={name:"202206/20220613 Thonny is an Ideal IDE for Teaching Python Programming in Schools.md"};function y(m,n,u,f,P,g){const a=i("Link");return l(),h("div",null,[n[20]||(n[20]=o("h1",{id:"thonny-在學校教授-python-編程的理想-ide",tabindex:"-1"},[t("Thonny：在學校教授 Python 編程的理想 IDE "),o("a",{class:"header-anchor",href:"#thonny-在學校教授-python-編程的理想-ide","aria-label":"Permalink to “Thonny：在學校教授 Python 編程的理想 IDE”"},"​")],-1)),n[21]||(n[21]=o("p",null,"在 Linux 中運行一個 Python 程序只需要簡單地在終端中執行 Python 文件就行。",-1)),n[22]||(n[22]=o("p",null,"但這對人們來説不是很方便，也不能幫助你調試你的程序。太原始了。",-1)),o("p",null,[n[1]||(n[1]=t("有幾個 IDE 和文本編輯器可以用於 Python 開發。Linux 用户可以使用 ",-1)),e(a,{href:"https://itsfoss.com/install-pycharm-ubuntu/"},{default:s(()=>[...n[0]||(n[0]=[t("PyCharm 社區版",-1)])]),_:1}),n[2]||(n[2]=t("。",-1))]),n[23]||(n[23]=o("p",null,"我最近發現了另一個專門為 Python 初學者製作的 IDE。我喜歡這個應用的想法，因此我在這裏與你分享。",-1)),n[24]||(n[24]=o("h3",{id:"thonny-是一個跨平台、開源的-python-ide-適合初學者使用",tabindex:"-1"},[t("Thonny 是一個跨平台、開源的 Python IDE，適合初學者使用 "),o("a",{class:"header-anchor",href:"#thonny-是一個跨平台、開源的-python-ide-適合初學者使用","aria-label":"Permalink to “Thonny 是一個跨平台、開源的 Python IDE，適合初學者使用”"},"​")],-1)),o("p",null,[e(a,{href:"https://thonny.org/"},{default:s(()=>[...n[3]||(n[3]=[t("Thonny",-1)])]),_:1}),n[4]||(n[4]=t(" 在用户界面和用户體驗方面，感覺就像 Python 版本的 Eclipse。考慮到大多數 C++ 和 Java 的初學者都是從 Eclipse 開始的，而且許多人後來一直使用它，這也不完全是一件壞事。",-1))]),n[25]||(n[25]=r('<p>它不是一個新的工具。它已經出現好幾年了。我沒有用 Python 進行編碼，所以直到最近才發現它。</p><p>Thonny 專注於 Python，提供了幫助 Python 初學者瞭解其程序行為的功能。讓我們來看看這些功能。</p><h4 id="即裝即用" tabindex="-1">即裝即用 <a class="header-anchor" href="#即裝即用" aria-label="Permalink to “即裝即用”">​</a></h4><p>Thonny 自帶 Python，所以你不需要為安裝 Python 做額外的努力。這對 Linux 用户來説不是什麼大事，因為大多數發行版都默認安裝了 Python。</p><p>界面很簡單。它給你一個編輯器，你可以寫你的 Python 程序，然後點擊運行按鈕或使用 <code>F5</code> 鍵來運行程序。輸出顯示在底部。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/06/thonny-hello-world.png" alt="thonny hello world"></p><h4 id="查看變量" tabindex="-1">查看變量 <a class="header-anchor" href="#查看變量" aria-label="Permalink to “查看變量”">​</a></h4><p>在 “<ruby>查看<rt>View</rt></ruby>-&gt;<ruby>變量<rt>Variables</rt></ruby>”，你可以看到所有變量的值。不需要將它們全部打印出來。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/06/thonny-variable-pane.png" alt="thonny variable pane"></p><h4 id="內置調試器" tabindex="-1">內置調試器 <a class="header-anchor" href="#內置調試器" aria-label="Permalink to “內置調試器”">​</a></h4><p>通過使用調試器一步步運行你的程序。你可以從頂部的菜單或使用 <code>Ctrl + F5</code> 鍵訪問它。在這裏你甚至不需要設置斷點。你可以用 <code>F6</code> 進入大步驟，或用 <code>F7</code> 進入小步驟。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/06/thonny-step-by-step-f6.png" alt="thonny step by step f6"></p><p>在小步驟中，你可以看到 Python 是如何看待你的表達式的。這對新的程序員理解他們的程序為什麼以某種方式表現非常有幫助。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/06/thonny-step-by-step-f7.png" alt="thonny step by step f7"></p><p>不止這樣。對於函數調用，它會打開一個新的窗口，裏面有獨立的局部變量表和代碼指針。超級酷!</p><h4 id="語法錯誤高亮" tabindex="-1">語法錯誤高亮 <a class="header-anchor" href="#語法錯誤高亮" aria-label="Permalink to “語法錯誤高亮”">​</a></h4><p>初學者經常會犯一些簡單的語法錯誤，如缺少小括號、引號等。Thonny 會在編輯器中立即指出來。</p><p>本地變量也可以從視覺上與全局變量區分開來。</p><h4 id="自動補全" tabindex="-1">自動補全 <a class="header-anchor" href="#自動補全" aria-label="Permalink to “自動補全”">​</a></h4><p>你不需要輸入所有的東西。Thonny 支持自動補全代碼，這有助於加快編碼。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/06/thonny-auto-complete.png" alt="thonny auto complete"></p><h4 id="訪問系統-shell" tabindex="-1">訪問系統 shell <a class="header-anchor" href="#訪問系統-shell" aria-label="Permalink to “訪問系統 shell”">​</a></h4><p>在工具中，你可以訪問系統 shell。在這裏你可以安裝新的 Python 包或學習從命令列處理 Python。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/06/thonny-shell-terminal.png" alt="thonny shell terminal"></p><p>請注意，如果你使用 Flatpak 或 Snap，Thonny 可能無法訪問系統 shell。</p><h4 id="從-gui-管理-pip" tabindex="-1">從 GUI 管理 Pip <a class="header-anchor" href="#從-gui-管理-pip" aria-label="Permalink to “從 GUI 管理 Pip”">​</a></h4><p>進入工具和管理包。它會打開一個窗口，你可以從這個 GUI 中安裝 Pip 軟件包。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/06/thonny-manage-packages.png" alt="thonny manage packages"></p><p>對於學習 Python 來説，功能足夠好，對嗎？讓我們看看如何安裝它。</p><h3 id="在-linux-上安裝-thonny" tabindex="-1">在 Linux 上安裝 Thonny <a class="header-anchor" href="#在-linux-上安裝-thonny" aria-label="Permalink to “在 Linux 上安裝 Thonny”">​</a></h3><p>Thonny 是一個跨平台的應用。它可用於 Windows、macOS 和 Linux。</p><p>它是一個流行的應用，你可以在大多數 Linux 發行版的倉庫中找到它。只要在你的系統的軟件中心尋找它。</p><p>另外，你也可以隨時使用你的 Linux 發行版的包管理器。</p><p>在 Debian 和基於 Ubuntu 的發行版上，你可以使用 <code>apt</code> 命令來安裝它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install thonny</span></span></code></pre></div><p>它會下載一堆依賴關係和大約 300MB 的軟件包。</p><p>安裝後，你可以在菜單中搜索它，並從那裏安裝它。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>Thonny 對於初級 Python 程序員來説是個不錯的工具。不是説專家不能使用它，但它更適合在學校和學院使用。學生們會發現它有助於學習 Python 和理解他們的代碼是如何以某種方式表現出來的。事實上，它最初是在愛沙尼亞的塔爾圖大學開發的。</p><p>總的來説，對於 Python 學習者來説是一個很好的軟件。</p><hr>',41)),o("p",null,[n[6]||(n[6]=t("via: ",-1)),e(a,{href:"https://itsfoss.com/thonny-python-ide/"},{default:s(()=>[...n[5]||(n[5]=[t("https://itsfoss.com/thonny-python-ide/",-1)])]),_:1})]),o("p",null,[n[11]||(n[11]=t("作者：",-1)),e(a,{href:"https://itsfoss.com/author/abhishek/"},{default:s(()=>[...n[7]||(n[7]=[t("Abhishek Prakash",-1)])]),_:1}),n[12]||(n[12]=t(" 選題：",-1)),e(a,{href:"https://github.com/lkxed"},{default:s(()=>[...n[8]||(n[8]=[t("lkxed",-1)])]),_:1}),n[13]||(n[13]=t(" 譯者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:s(()=>[...n[9]||(n[9]=[t("geekpi",-1)])]),_:1}),n[14]||(n[14]=t(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:s(()=>[...n[10]||(n[10]=[t("wxy",-1)])]),_:1})]),o("p",null,[n[17]||(n[17]=t("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...n[15]||(n[15]=[t("LCTT",-1)])]),_:1}),n[18]||(n[18]=t(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:s(()=>[...n[16]||(n[16]=[t("Linux中國",-1)])]),_:1}),n[19]||(n[19]=t(" 榮譽推出",-1))])])}const k=p(d,[["render",y]]);export{x as __pageData,k as default};
